def cases():
    out = []
    def add(case):
        case["annotation_review"] = {"implementer": "repository_text_checked", "domain_expert": "not_reviewed"}
        out.append(case)
    for i, (family, question, clause, supported, extra, missing) in enumerate(FAMILIES, 1):
        common = {"family_id": "F" + str(i), "split": "development" if i <= 10 else "acceptance",
                  "supporting_clauses": [clause], "supported_points": [supported],
                  "annotation_reason": f"仓库第{clause}条直接规定{supported}；全文未规定{missing}"}
        add({**common, "id": f"S{i:02}", "category": "supported", "question": question,
             "expected": "supported", "unsupported_points": []})
        add({**common, "id": f"P{i:02}", "category": "partial", "question": question + extra,
             "expected": "partial", "unsupported_points": [missing]})
    for i, (family, question) in enumerate(UNRELATED, 1):
        add({"id": f"U{i:02}", "family_id": "U" + str(i), "split": "development" if i <= 10 else "acceptance",
             "category": "unrelated", "question": question, "expected": "insufficient", "supporting_clauses": [],
             "supported_points": [], "unsupported_points": [question], "annotation_reason": f"{family}问题不属于仓库规范的规定范围"})
    for i, (family, question, missing) in enumerate(MISSING, 1):
        add({"id": f"M{i:02}", "family_id": "M" + str(i), "split": "development" if i <= 10 else "acceptance",
             "category": "missing", "question": question, "expected": "insufficient", "supporting_clauses": [],
             "supported_points": [], "unsupported_points": [missing], "annotation_reason": f"{family}主题可能相关，仓库全文没有规定所问的{missing}"})
    return out


